class Money private constructor(val minor: Long, val currency: String) {
    init { require(currency.length == 3) { "bad currency" } }

    fun plus(other: Money) = Money(minor + other.minor, currency)

    companion object { fun of(minor: Long, currency: String) = Money(minor, currency) }
}

private fun normalise(code: String) = code.uppercase()   // file-private helper
